function cq2Histo(R, ex) { const P = R.pdf, M = R.M, tw = R.W; const pv = prevEx(ex); const se = cq2Series(ex); const n = se[se.length - 1]; const p = pv ? se.find(x => x.y === pv.fin.slice(0, 4)) : null; const pal = cq2Pal();
  const cats = [["Chiffre d'affaires", "ca"], ["Valeur ajoutée", "va"], ["Excédent brut d'exploitation", "ebe"], ["Résultat net", "rn"], ["Capacité d'autofinancement", "caf"]];
  const vals = cats.flatMap(([, k]) => [n[k], p ? p[k] : 0]); const mx = Math.max(1, ...vals), mn = Math.min(0, ...vals); const H = cq2HC(); R.ensure(H + 64); R.h2("Principaux soldes" + (p ? " · " + n.y + " comparé à " + p.y : " " + n.y));
  const top = R.y + 12, zero = top + H * mx / (mx - mn); const gw = tw / cats.length; const bw = Math.min(34, (gw - 26) / (p ? 2 : 1));
  P.line(M, zero, M + tw, zero, "#9CA3AF", 0.5);
  cats.forEach(([l, k], i) => { const x0 = M + i * gw + (gw - bw * (p ? 2 : 1) - (p ? 4 : 0)) / 2; const bar = (v, x, col, lab) => { const h = Math.abs(v) * H / (mx - mn); const y = v >= 0 ? zero - h : zero; P.rect(x, y, bw, Math.max(0.6, h), col); P.text(x + bw / 2, v >= 0 ? y - 3 : y + h + 8, cq2KE(v), { size: 6.3, color: "#374151", align: "center" }); };
    bar(n[k], x0, pal[0]); if (p) bar(p[k], x0 + bw + 4, pal[1]); const words = l.split(" "); let ln = "", L = []; words.forEach(w => { if (textW(ln + " " + w, 7) > gw - 6 && ln) { L.push(ln); ln = w; } else ln = ln ? ln + " " + w : w; }); L.push(ln); L.forEach((t, j) => P.text(M + i * gw + gw / 2, top + H + 14 + j * 8.5, pdfClean(t), { size: 7, color: "#374151", align: "center" })); });
  R.y = top + H + 34; P.rect(M, R.y - 6, 8, 6, pal[0]); P.text(M + 12, R.y, n.y, { size: 7 }); if (p) { P.rect(M + 50, R.y - 6, 8, 6, pal[1]); P.text(M + 62, R.y, p.y, { size: 7 }); } R.y += 12; }
function cq2Courbe(R, ex) { const P = R.pdf, M = R.M, tw = R.W; const se = cq2Series(ex); if (se.length < 2) return false; const pal = cq2Pal(); const L = [["Chiffre d'affaires", "ca", pal[0]], ["Excédent brut d'exploitation", "ebe", pal[2]], ["Résultat net", "rn", pal[3]]];
  const vals = se.flatMap(s => L.map(x => s[x[1]])); const mx = Math.max(1, ...vals), mn = Math.min(0, ...vals); const H = cq2HC(); R.ensure(H + 60); R.h2("Évolution sur " + se.length + " exercices");
  const x0 = M + 46, w = tw - 60, top = R.y + 8; const Y = v => top + H - (v - mn) * H / (mx - mn); const X = i => x0 + (se.length === 1 ? w / 2 : i * w / (se.length - 1));
  for (let g = 0; g <= 4; g++) { const v = mn + (mx - mn) * g / 4; const y = Y(v); P.line(x0, y, x0 + w, y, g === 0 || Math.abs(v) < 1 ? "#9CA3AF" : "#E5E7EB", 0.4); P.text(x0 - 6, y + 2.5, cq2KE(v), { size: 6.3, color: "#6B7280", align: "right" }); }
  if (mn < 0) P.line(x0, Y(0), x0 + w, Y(0), "#9CA3AF", 0.6);
  se.forEach((s, i) => P.text(X(i), top + H + 12, s.y, { size: 7, color: "#374151", align: "center" }));
  L.forEach(([l, k, col]) => { se.forEach((s, i) => { if (i) P.line(X(i - 1), Y(se[i - 1][k]), X(i), Y(s[k]), col, 1.6); P.rect(X(i) - 2, Y(s[k]) - 2, 4, 4, col); }); P.text(X(se.length - 1) + 4, Y(se[se.length - 1][k]) + 2.5, cq2KE(se[se.length - 1][k]), { size: 6.3, color: col }); });
  R.y = top + H + 26; let lx = M; L.forEach(([l, , col]) => { P.rect(lx, R.y - 6, 8, 6, col); P.text(lx + 12, R.y, pdfClean(l), { size: 7 }); lx += 20 + textW(pdfClean(l), 7); }); R.y += 12; return true; }
function cq2Repart(R, ex) { const P = R.pdf, M = R.M, tw = R.W; const c = compteResultat(ex.debut, ex.fin); const v = k => c.v(k); if (c.CA <= 0) return; const pal = cq2Pal(); const rn = c.RN;
  const parts = [["Achats consommés", v("C_am") + v("C_vsm") + v("C_amp") + v("C_vsmp")], ["Charges externes", v("C_ace")], ["Impôts et taxes", v("C_imp")], ["Personnel", v("C_sal") + v("C_soc")], ["Amortissements et provisions", v("C_dam") + v("C_dpr")], ["Autres charges", Math.max(0, v("C_ach") + v("C_fin") + v("C_exc") + v("C_part") + v("C_is") - v("P_fin") - v("P_exc") - v("P_rep") - v("P_apr"))], [rn >= 0 ? "Résultat" : "Perte", Math.max(0, rn)]].filter(x => x[1] / c.CA >= 0.005);
  const tot = parts.reduce((a, x) => a + x[1], 0) || 1; R.ensure(80); R.h2("Répartition de 100 € de chiffre d'affaires"); let x = M; parts.forEach(([l, a], i) => { const w = tw * a / tot; P.rect(x, R.y, w, 16, pal[i % pal.length]); if (w > 24) P.text(x + w / 2, R.y + 11, Math.round(a / c.CA * 100) + " €", { size: 7, bold: true, color: i === 1 || i === 5 ? "#111827" : "#FFFFFF", align: "center" }); x += w; }); R.y += 28;
  parts.forEach(([l, a], i) => { const cx = M + (i % 4) * (tw / 4), cy = R.y + Math.floor(i / 4) * 12; P.rect(cx, cy - 6, 7, 7, pal[i % pal.length]); P.text(cx + 11, cy, pdfClean(l + " " + Math.round(a / c.CA * 100) + " €"), { size: 6.8, color: "#374151" }); }); R.y += Math.ceil(parts.length / 4) * 12 + 8; }
(function () { const F = CQ2_F; const _r = F.resume; F.resume = ctx => { _r(ctx); if (!cq2Sob()) return; const syn = cq2St().opt.syn || "mixte"; const R = ctx.R, ex = ctx.ex;
  try { if (["histo", "mixte", "complet", "graph"].includes(syn)) cq2Histo(R, ex); let ok = true; if (["courbe", "mixte", "complet", "graph"].includes(syn)) ok = cq2Courbe(R, ex); if (syn === "courbe" && !ok) cq2Histo(R, ex); if (["complet", "graph"].includes(syn)) cq2Repart(R, ex); } catch (e) { logErr("synthèse graphique", e); } }; })();
/* ---------- écran : couleurs, modèle de synthèse, attestation et commentaire modifiables ---------- */
(function () { const _v = VIEWS.compAnn; VIEWS.compAnn = function () { const Q = cq2St(); const ex = exCur(); let h = _v.apply(this, arguments);
  h = h.replace(`<label class="f">Style de la plaquette<select`, `<label class="f">Synthèse de l'exercice<select class="in" data-ch="cq2Opt" data-k="syn">${CQ2_SYN.map(([v, l]) => `<option value="${v}" ${(Q.opt.syn || "mixte") === v ? "selected" : ""}>${l}</option>`).join("")}</select></label>${cq2YN("col", "Couleurs dans la plaquette (en-têtes, titres, totaux, graphiques)")}<label class="f">Style de la plaquette<select`);
  const ta = (k, rows) => { const custom = Q.texts[k] != null && Q.texts[k] !== ""; return `<textarea class="in cq2-ta" rows="${rows}" data-ch="cq2Txt" data-k="${k}">${esc(cq2X(k, ex))}</textarea><div class="row" style="justify-content:space-between;margin:4px 0 10px"><span class="small muted">${custom ? "✎ Texte personnalisé" : "Texte calculé automatiquement depuis vos comptes"}</span>${custom ? `<button class="btn sm ghost" data-act="cq2TxtAuto" data-k="${k}">↺ Texte automatique</button>` : ""}</div>`; };
  const ck = (k) => (CQ2_EL[k] || []).map(([e, l]) => `<label class="cq2-ck"><input type="checkbox" ${cq2El(k, e) ? "checked" : ""} data-ch="cq2El" data-k="${k}.${e}"> ${esc(l)}</label>`).join("");
  const panel = `<section class="panel cq2-att"><div class="panel-h"><h2>✍ Attestation et commentaire</h2></div><div class="panel-b">
    <div class="row" style="justify-content:space-between"><b>Attestation de l'expert-comptable</b><label class="cq2-ck" style="padding:0"><input type="checkbox" ${cq2On("rapport") ? "checked" : ""} data-ch="cq2On" data-k="rapport"> Inclure</label></div>
    <div class="cq2-els">${ck("rapport")}</div>${ta("rapport", 9)}<p class="small muted" style="margin:-6px 0 12px">La ligne [CHIFFRES] place le tableau total du bilan / chiffre d'affaires / résultat. Un paragraphe par ligne.</p>
    <div class="row" style="justify-content:space-between"><b>Commentaire sur l'exercice</b><label class="cq2-ck" style="padding:0"><input type="checkbox" ${cq2On("comment") ? "checked" : ""} data-ch="cq2On" data-k="comment"> Inclure</label></div>
    <div class="cq2-els">${ck("comment")}</div>${ta("comment", 9)}</div></section>`;
  h = h.replace(`<section class="panel"><div class="panel-h"><h2>⚙ Paramètres</h2>`, panel + `<section class="panel"><div class="panel-h"><h2>⚙ Paramètres</h2>`);
  return h; }; })();
